import json
from pathlib import Path


def load_scores(path):
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    if set(data) != {"scores"} or not isinstance(data["scores"], list):
        raise ValueError("scores.json must contain only a scores list")
    if any(type(value) is not int for value in data["scores"]):
        raise ValueError("every score must be an integer")
    return data["scores"]


def highest(values):
    if not values:
        raise ValueError("at least one score is required")
    return max(values)


def main():
    values = load_scores(Path(__file__).with_name("scores.json"))
    print(f"highest={highest(values)}")


if __name__ == "__main__":
    main()

