import ast
import json
import sys
import tomllib
from pathlib import Path

REQUIRED = (
    "AGENTS.md",
    "README.md",
    "pyproject.toml",
    "ledger_report.py",
    "scores.json",
    "tests/test_ledger_report.py",
    "old-design.md",
)

RECORD_KEYS = {
    "repository",
    "root",
    "outcome",
    "in_scope",
    "out_of_scope",
    "governing_instructions",
    "branch_worktree",
    "runtime_boundaries",
    "entrypoints",
    "flow",
    "standard_checks",
    "sensitive_generated",
    "unknowns",
    "rollback",
    "evidence",
}

LIST_FIELDS = {
    "in_scope",
    "out_of_scope",
    "governing_instructions",
    "runtime_boundaries",
    "entrypoints",
    "standard_checks",
    "sensitive_generated",
    "unknowns",
}


def fail(message):
    print(f"FAIL: {message}")
    raise SystemExit(1)


def read_text(path):
    try:
        return path.read_text(encoding="utf-8")
    except OSError as exc:
        fail(f"cannot read {path}: {exc}")


def require_string(value, label):
    if not isinstance(value, str) or not value.strip():
        fail(f"{label} must be a non-empty string")


def parse_json(path, label):
    try:
        return json.loads(read_text(path))
    except json.JSONDecodeError as exc:
        fail(f"{label} is invalid JSON: {exc}")


def direct_function(tree, name):
    return next(
        (node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == name),
        None,
    )


def is_name(node, name):
    return isinstance(node, ast.Name) and node.id == name


def is_testcase_base(node):
    return (
        is_name(node, "TestCase")
        or (
            isinstance(node, ast.Attribute)
            and node.attr == "TestCase"
        )
    )


def intended_testcase_class(tree):
    candidates = [
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef)
        and any(is_testcase_base(base) for base in node.bases)
    ]
    if len(candidates) != 1:
        fail(
            "tests must contain exactly one top-level class inheriting from "
            "unittest.TestCase"
        )
    return candidates[0]


def direct_method(test_class, name):
    return next(
        (
            node
            for node in test_class.body
            if isinstance(node, ast.FunctionDef) and node.name == name
        ),
        None,
    )


def assertion_methods(function):
    found = set()

    def visit(node):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            return
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
        ):
            found.add(node.func.attr)
        for child in ast.iter_child_nodes(node):
            visit(child)

    for statement in function.body:
        visit(statement)
    return found


def validate_highest(tree):
    function = direct_function(tree, "highest")
    if function is None:
        fail("ledger_report.py lacks a top-level highest function")
    positional = function.args.posonlyargs + function.args.args
    if len(positional) != 1 or positional[0].arg != "values":
        fail("highest must take exactly one positional argument named values")
    if len(function.body) != 2:
        fail("highest must have the inspected guard-and-return structure")
    guard, result = function.body
    guard_ok = (
        isinstance(guard, ast.If)
        and isinstance(guard.test, ast.UnaryOp)
        and isinstance(guard.test.op, ast.Not)
        and is_name(guard.test.operand, "values")
        and len(guard.body) == 1
        and isinstance(guard.body[0], ast.Raise)
        and isinstance(guard.body[0].exc, ast.Call)
        and is_name(guard.body[0].exc.func, "ValueError")
        and not guard.orelse
    )
    return_ok = (
        isinstance(result, ast.Return)
        and isinstance(result.value, ast.Call)
        and is_name(result.value.func, "max")
        and len(result.value.args) == 1
        and is_name(result.value.args[0], "values")
        and not result.value.keywords
    )
    if not guard_ok or not return_ok:
        fail("highest does not match the inspected empty guard followed by return max(values)")


def validate_main_structure(tree):
    function = direct_function(tree, "main")
    if function is None:
        fail("ledger_report.py lacks a top-level main function")
    called_names = {
        node.func.id
        for node in ast.walk(function)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
    }
    missing = {"load_scores", "highest", "print"} - called_names
    if missing:
        fail("main lacks structurally required calls: " + ", ".join(sorted(missing)))


def validate_test_structure(tree):
    test_class = intended_testcase_class(tree)
    normal = direct_method(test_class, "test_highest_score")
    negative = direct_method(test_class, "test_empty_scores_are_rejected")
    if normal is None or negative is None:
        fail(
            "the intended TestCase class must contain both required direct methods"
        )
    normal_assertions = assertion_methods(normal)
    negative_assertions = assertion_methods(negative)
    if "assertEqual" not in normal_assertions:
        fail("test_highest_score lacks an assertEqual structure")
    if "assertRaises" not in negative_assertions:
        fail("test_empty_scores_are_rejected lacks an assertRaises structure")


def main():
    if len(sys.argv) != 3:
        fail("usage: python3 tools/check_orientation.py FIXTURE_DIR ORIENTATION_JSON")

    root = Path(sys.argv[1]).resolve()
    record_path = Path(sys.argv[2]).resolve()
    if not root.is_dir():
        fail("fixture directory is missing")

    missing = [relative for relative in REQUIRED if not (root / relative).is_file()]
    if missing:
        fail("missing required fixture files: " + ", ".join(missing))

    supplied = {
        path.relative_to(root).as_posix()
        for path in root.rglob("*")
        if path.is_file()
        and "__pycache__" not in path.parts
        and path.suffix != ".pyc"
    }
    if supplied != set(REQUIRED):
        extra = sorted(supplied - set(REQUIRED))
        absent = sorted(set(REQUIRED) - supplied)
        fail(f"fixture file set is not exact; extra={extra}, missing={absent}")

    record = parse_json(record_path, "orientation record")
    if not isinstance(record, dict) or set(record) != RECORD_KEYS:
        fail("orientation record must have exactly the documented fields")

    for field in RECORD_KEYS - LIST_FIELDS - {"evidence"}:
        require_string(record[field], field)
    for field in LIST_FIELDS:
        value = record[field]
        if not isinstance(value, list) or not value:
            fail(f"{field} must be a non-empty list")
        for index, item in enumerate(value):
            require_string(item, f"{field}[{index}]")

    if record["in_scope"] != list(REQUIRED):
        fail("in_scope must list the seven fixture files in documented order")
    if "UNKNOWN" not in record["branch_worktree"]:
        fail("unavailable branch and worktree state must remain explicit UNKNOWN")

    evidence = record["evidence"]
    if not isinstance(evidence, list) or not evidence:
        fail("evidence must be a non-empty list")
    evidence_paths = []
    for index, item in enumerate(evidence):
        if not isinstance(item, dict) or set(item) != {"path", "supports"}:
            fail(f"evidence[{index}] must contain exactly path and supports")
        require_string(item["path"], f"evidence[{index}].path")
        require_string(item["supports"], f"evidence[{index}].supports")
        evidence_paths.append(item["path"])
    if evidence_paths != list(REQUIRED) or len(set(evidence_paths)) != len(evidence_paths):
        fail("evidence paths must agree exactly with in_scope without duplicates")

    scores = parse_json(root / "scores.json", "scores.json")
    if not isinstance(scores, dict) or set(scores) != {"scores"}:
        fail("scores.json must contain exactly the scores field")
    values = scores["scores"]
    if values != [4, 9, 5] or any(type(value) is not int for value in values):
        fail("scores.json must contain the integer list [4, 9, 5]")

    try:
        pyproject = tomllib.loads(read_text(root / "pyproject.toml"))
    except tomllib.TOMLDecodeError as exc:
        fail(f"pyproject.toml is invalid TOML: {exc}")
    project = pyproject.get("project")
    if not isinstance(project, dict):
        fail("pyproject.toml lacks a project table")
    scripts = project.get("scripts")
    if scripts != {"ledger-report": "ledger_report:main"}:
        fail("project.scripts must declare only ledger-report -> ledger_report:main")
    if project.get("requires-python") != ">=3.11":
        fail("project requires-python must be >=3.11")

    try:
        implementation = ast.parse(read_text(root / "ledger_report.py"))
        tests = ast.parse(read_text(root / "tests/test_ledger_report.py"))
    except SyntaxError as exc:
        fail(f"Python structural evidence cannot be parsed: {exc}")
    validate_highest(implementation)
    validate_main_structure(implementation)
    validate_test_structure(tests)

    expected_flow = "scores.json [4, 9, 5] -> load_scores -> highest -> max -> main -> stdout highest=9"
    if record["flow"] != expected_flow:
        fail("flow does not match the parsed baseline fixture facts")
    if record["entrypoints"] != [
        "ledger-report -> ledger_report:main",
        "python3 ledger_report.py -> module main guard",
    ]:
        fail("entrypoints do not match parsed configuration and source structure")

    print("PASS: orientation record matches parsed fixture facts and structural evidence")


if __name__ == "__main__":
    main()

import json
