    return data["scores"]


def highest(values):
    if not values:
        raise ValueError("at least one score is required")
    return max(values)


def summarize(values):
    return {"highest": highest(values), "count": len(values)}


def main():
    values = load_scores(Path(__file__).with_name("scores.json"))
    print(json.dumps(summarize(values)))


if __name__ == "__main__":
    main()

